const fs = require('fs');

function main() {
    const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (data.length < 2) return;
    const s = data[1];
    const n = s.length;
    let ans = n;
    for (let i = 1; i <= Math.floor(n / 2); i++) {
        if (s.substring(0, i) === s.substring(i, 2 * i)) {
            ans = Math.min(ans, n - i + 1);
        }
    }
    console.log(ans);
}

main();

const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
let inputIdx = 0;
const readWordString = () => input[inputIdx++];
const writeNumber = (val) => process.stdout.write(val + ' ');
const writeLine = () => process.stdout.write('\n');

function countLength(left, right) {
    return left > right ? 0 : right - left + 1;
}
function getRight(left, count) {
    return left + count - 1;
}
function* seq(low, high, skip = 1) {
    for (let i = low; i <= high; i += skip) yield i;
}
function sequenceEqual(arr1, arr2) {
    if (arr1.length !== arr2.length) return false;
    for (let i = 0; i < arr1.length; i++) if (arr1[i] !== arr2[i]) return false;
    return true;
}

function main() {
    readWordString();
    const s = readWordString().split('');
    const n = s.length;
    const upb = n - 1;

    let res = n;

    for (const i of seq(1, upb)) {
        if (countLength(0, i - 1) > countLength(i, upb)) break;

        const len = countLength(0, i - 1);
        const right = getRight(i, len);

        if (right >= n) continue;

        const sub1 = s.slice(0, i);
        const sub2 = s.slice(i, right + 1);

        if (sequenceEqual(sub1, sub2)) {
            const candidate = 1 + n - i;
            if (candidate < res) res = candidate;
        }
    }

    writeNumber(res);
    writeLine();
}

main();

