const fs = require('fs');

const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
let inputIndex = 0;

function readWordString() {
    if (inputIndex >= input.length) throw new Error("EOF");
    return input[inputIndex++];
}

function writeNumber(num) {
    process.stdout.write(String(num) + ' ');
}

function writeLine() {
    process.stdout.write('\n');
}

function seq(low, high) {
    const arr = [];
    for (let i = low; i <= high; i++) arr.push(i);
    return arr;
}

function countLength(left, right) {
    return left > right ? 0 : right - left + 1;
}

function getRight(left, count) {
    return left + count - 1;
}

function main() {
    readWordString(); // Discard first token
    const s = readWordString().split('');
    const n = s.length;
    const upb = n - 1;
    let res = n;

    for (let i = 1; i <= upb; i++) {
        if (countLength(0, i - 1) > countLength(i, upb)) break;

        const len = countLength(0, i - 1);
        let equal = true;
        for (let k = 0; k < len; k++) {
            if (s[k] !== s[i + k]) {
                equal = false;
                break;
            }
        }

        if (equal) {
            const val = 1 + i + (n - i - len); // Equivalent to 1 + n - i
            if (val < res) res = val;
        }
    }

    writeNumber(res);
    writeLine();
}

main();

